package main
import("context";"os/exec";"encoding/json";"errors";"io";"net/http";"net/url";"os";"strings";"sync";"time")
const wifiUnifyPath="/data/airlink/wifi-unify.json"
var wifiUnifyMu sync.Mutex
var wifiUnifyPending bool
var wifiUnifyMessage string
var wifiProfileFields=[]string{"ssid","auth_mode","crypto","wpa_psk","wpa_mode","radio_x"}
type wifiProfile map[string]string
type wifiUnifyConfig struct{Enabled bool `json:"enabled"`;Original map[string]wifiProfile `json:"original,omitempty"`}
func wifiConfig()wifiUnifyConfig{var c wifiUnifyConfig;b,e:=os.ReadFile(wifiUnifyPath);if e==nil{_ = json.Unmarshal(b,&c)};return c}
func saveWifiConfig(c wifiUnifyConfig)error{b,e:=json.Marshal(c);if e!=nil{return e};if e=os.WriteFile(wifiUnifyPath+".tmp",b,0600);e!=nil{return e};return os.Rename(wifiUnifyPath+".tmp",wifiUnifyPath)}
func wifiUnifyManaged()bool{wifiUnifyMu.Lock();defer wifiUnifyMu.Unlock();return wifiUnifyPending||wifiConfig().Enabled}
func wifiValue(key string)string{ctx,cancel:=context.WithTimeout(context.Background(),3*time.Second);defer cancel();b,e:=exec.CommandContext(ctx,"nvram","get",key).CombinedOutput();if e!=nil{return ""};return strings.TrimSuffix(strings.TrimSuffix(string(b),"\n"),"\r")}
func readWifiProfiles()map[string]wifiProfile{result:=map[string]wifiProfile{};for _,prefix:=range []string{"rt_","wl_"}{p:=wifiProfile{};for _,key:=range wifiProfileFields{p[key]=wifiValue(prefix+key)};result[prefix]=p};return result}
func validWifiProfile(p wifiProfile)bool{return len([]byte(p["ssid"]))>0&&len([]byte(p["ssid"]))<=32&&!strings.ContainsAny(p["ssid"],"\x00\r\n")&&p["auth_mode"]=="psk"&&(p["crypto"]=="aes"||p["crypto"]=="tkip+aes"||p["crypto"]=="tkip")&&(p["wpa_mode"]=="0"||p["wpa_mode"]=="1"||p["wpa_mode"]=="2")&&len(p["wpa_psk"])>=8&&len(p["wpa_psk"])<=63&&(p["radio_x"]=="0"||p["radio_x"]=="1")}
func unifiedWifiProfiles(profiles map[string]wifiProfile)map[string]wifiProfile{result:=map[string]wifiProfile{};for _,prefix:=range []string{"rt_","wl_"}{p:=wifiProfile{};for _,key:=range wifiProfileFields{p[key]=profiles["rt_"][key]};p["radio_x"]="1";result[prefix]=p};return result}
func wifiProfilesMatch(a,b map[string]wifiProfile)bool{for _,prefix:=range []string{"rt_","wl_"}{for _,key:=range wifiProfileFields{if a[prefix]==nil||b[prefix]==nil||a[prefix][key]!=b[prefix][key]{return false}}};return true}
func wifiIsUnified(profiles map[string]wifiProfile)bool{if !validWifiProfile(profiles["rt_"])||!validWifiProfile(profiles["wl_"]){return false};return profiles["rt_"]["radio_x"]=="1"&&profiles["wl_"]["radio_x"]=="1"&&wifiProfilesMatch(profiles,unifiedWifiProfiles(profiles))}
func wifiApplyValues(profiles map[string]wifiProfile,two,five string)(url.Values,error){v:=url.Values{};for _,pair:=range []struct{prefix,html string}{{"rt_",two},{"wl_",five}}{names:=map[string]bool{};for _,m:=range nameRE.FindAllStringSubmatch(pair.html,-1){names[m[1]]=true};for _,key:=range wifiProfileFields{field:=pair.prefix+key;if !names[field]{return nil,errors.New("固件无线表单不匹配，未发送修改。")};v.Set(field,profiles[pair.prefix][key])}};if hiddenValue(two,"action_script")!="restart_wifis"||hiddenValue(five,"action_script")!="restart_wifis"{return nil,errors.New("固件未提供已核对的双频应用动作。")};v.Set("sid_list",hiddenValue(two,"sid_list")+hiddenValue(five,"sid_list"));v.Set("action_mode"," Apply ");v.Set("action_script","restart_wifis");v.Set("current_page",pages["wifi2"]);v.Set("next_page","");v.Set("next_host","");return v,nil}
func applyWifiUnify(v url.Values,expected map[string]wifiProfile,c wifiUnifyConfig,enabled bool){time.Sleep(time.Second);message:="提交未确认，请重新连接 Wi-Fi 后刷新状态；关闭开关可恢复备份。";req,_:=http.NewRequest("POST","http://127.0.0.1/start_apply.htm",strings.NewReader(v.Encode()));req.Header.Set("Content-Type","application/x-www-form-urlencoded");req.Header.Set("Referer","http://127.0.0.1/"+pages["wifi2"]);res,e:=client.Do(req);if e==nil{reply,_:=io.ReadAll(io.LimitReader(res.Body,128<<10));res.Body.Close();if res.StatusCode==200&&!strings.Contains(string(reply),"alert(")&&!strings.Contains(strings.ToLower(string(reply)),"invalid"){for i:=0;i<8;i++{if wifiProfilesMatch(readWifiProfiles(),expected){wifiUnifyMu.Lock();c.Enabled=enabled;if !enabled{c.Original=nil};err:=saveWifiConfig(c);wifiUnifyMu.Unlock();if err!=nil{message="无线配置已回读，但管理记录保存失败，请刷新检查。"}else if enabled{message="已回读确认双频同名配置；请连接原 2.4G Wi-Fi 名称。"}else{message="已回读确认恢复两路 Wi-Fi 原配置。"};break};time.Sleep(time.Second)}}};wifiUnifyMu.Lock();wifiUnifyMessage=message;wifiUnifyPending=false;wifiUnifyMu.Unlock()}
func wifiUnifyAPI(w http.ResponseWriter,r *http.Request){wifiUnifyMu.Lock();defer wifiUnifyMu.Unlock();c:=wifiConfig();if r.Method=="GET"{profiles:=readWifiProfiles();if demo{profiles=map[string]wifiProfile{"rt_":{"ssid":"5G MIFI","auth_mode":"psk","crypto":"aes","wpa_psk":"preview-only","wpa_mode":"2","radio_x":"1"},"wl_":{"ssid":"5G MIFI_5G","auth_mode":"psk","crypto":"aes","wpa_psk":"preview-only","wpa_mode":"2","radio_x":"1"}}};supported:=validWifiProfile(profiles["rt_"])&&validWifiProfile(profiles["wl_"]);out(w,map[string]any{"managed":c.Enabled,"enabled":wifiIsUnified(profiles),"pending":wifiUnifyPending,"message":wifiUnifyMessage,"ssid":profiles["rt_"]["ssid"],"ssid5":profiles["wl_"]["ssid"],"supported":supported,"restore_available":len(c.Original)==2});return};if r.Method!="POST"{fail(w,405,"请使用保存按钮。");return};var b struct{Enabled *bool `json:"enabled"`};if body(r,&b)!=nil||b.Enabled==nil{fail(w,400,"请选择开关状态。");return};if wifiUnifyPending{fail(w,409,"正在应用无线配置，请稍后再试。");return};if demo{out(w,map[string]any{"ok":true,"message":"预览模式不会修改 Wi-Fi。"});return};profiles:=readWifiProfiles();if !validWifiProfile(profiles["rt_"])||!validWifiProfile(profiles["wl_"]){fail(w,400,"请先将两路 Wi-Fi 配置为个人密码加密，设置有效名称和 8–63 位密码。");return};expected:=profiles;enabled:=*b.Enabled;if enabled{if c.Enabled{fail(w,409,"已启用双频合一，请先关闭后再重新启用。");return};c.Original=profiles;c.Enabled=true;expected=unifiedWifiProfiles(profiles)}else{if len(c.Original)!=2||!validWifiProfile(c.Original["rt_"])||!validWifiProfile(c.Original["wl_"]){fail(w,409,"没有可恢复的合并前配置，请分别设置两路 Wi-Fi。");return};expected=c.Original};two,e:=native(pages["wifi2"]);if e!=nil{fail(w,502,"无法读取 2.4G 固件表单。");return};five,e:=native(pages["wifi5"]);if e!=nil{fail(w,502,"无法读取 5G 固件表单。");return};values,e:=wifiApplyValues(expected,two,five);if e!=nil{fail(w,502,e.Error());return};if e=saveWifiConfig(c);e!=nil{fail(w,500,"无法保存恢复备份，未修改无线配置。");return};wifiUnifyPending=true;wifiUnifyMessage="正在应用无线配置，Wi-Fi 可能短暂断开，请重新连接后刷新。";go applyWifiUnify(values,expected,c,enabled);out(w,map[string]any{"ok":true,"pending":true,"message":wifiUnifyMessage})}
